static void __stdcall OBJMODE_DispatchOperateCallback(D2ObjectOperateFnArg * pOperation, uint8_t nFunctionId) {
    BOOL _bBadCallback;
    bool bBadCallback;
    bool bActAllowed;
    D2RoomStrc* pRoom;
    int32_t nErrorLine;
    uint32_t uFunctionIdx = (uint32_t)nFunctionId;
    if (!((int)uFunctionIdx < gnObjectOperateCallbackCount && gapObjectOperateCallbacks[uFunctionIdx])) {
      return;
    }

    /* FARPROC lpfn for IsBadCodePtr */ _bBadCallback = IsBadCodePtr((FARPROC)gapObjectOperateCallbacks[uFunctionIdx]);
    if (_bBadCallback) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x56c);
      exit(-1);
    }
    if (gapObjectOperateCallbacks[uFunctionIdx] == OBJMODE_SpawnRandomMonsters) {
      nErrorLine = ObjectsRgn::OBJECT_HandleObjectMode(&pOperation->sArg);
      pRoom = D2Common::Units::UNITS_GetRoom(pOperation->sArg.pVictim);
      _bBadCallback = OBJMODE_CheckSpawnMonsterFromSkeletonActRestriction(nErrorLine, pRoom);
      if (!_bBadCallback) {
        return;
      }
    }

    ::SGAMEDATA* pGame = pOperation->sArg.pGame;
    GAME::Event::SetEvent(pGame, pOperation->sArg.pVictim, 4, pGame->dwGameFrame + 0x23, 0, 0);
    UNIT::SUnit::SetupUpdateEvent_AttachEventSound(pOperation->sArg.pVictim, UNITEVENTCALLBACK_REFRESHVENDOR, nullptr);
}

static BOOL OBJMODE_CheckInventoryHasItemType(eD2ItemTypes eItemType, D2UnitStrc * pUnit) {
    D2UnitStrc* pCarriedItem;
    uint32_t bMatchesType;
    if (!pUnit->pInventory) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x6d3);
      exit(-1);
    }

    D2UnitStrc* pInvItem = D2Common::INVENTORY::Inventory::INVENTORY_GetFirstItem(pUnit->pInventory);
    while (true) {
      if (!pInvItem) {
        return 0;
      }

      pCarriedItem = D2Common::INVENTORY::Inventory::GetCarriedItem(pInvItem);
      bMatchesType = D2Common::ITEMS::Items::ITEMS_IsA(pCarriedItem, eItemType);
      if (bMatchesType) {
        break;
      }

      pInvItem = D2Common::INVENTORY::Inventory::INVENTORY_GetNextItem(pInvItem);
    }

    return 1;
}

// Object operate-fn for the Horadric Cube chest object. If the cube is closed (Death mode or null) and the player is not already trading: checks the player's inventory for a Gem-type item (required to open the cube); if absent plays a sound. If a gem is present, sets interact info to the cube's GUID, marks the cube open (SetupUpdateFlag 3), and sends SCMD 0x58 (OpenUI) to the client. If the cube is already open (Run mode) and it matches the current NPC interaction, closes it (ClearInteractInfo, SetupUpdateFlag 1). Always returns 1.
// @sourcefile .\OBJECTS\ObjMode.cpp
BOOL __fastcall OBJOP_OpenHoradricCube(D2ObjectOperateFnArg * pOperation) {
    BOOL _bHasGemInInventory;
    bool bHasGemInInventory;
    uint32_t nCubeUnitGUID;
    D2GSPacketSrv0x58 sPacket;
    D2UnitStrc* pNpc = UNIT::SUnit::GetInteractedNpc(pOperation->sArg.pGame, pOperation->pAttacker);
    D2ClientStrc* pClient = UNIT::SUnit::SUNIT_GetClient(pOperation->pAttacker, ".\\OBJECTS\\ObjMode.cpp", 0x6ec);
    D2UnitStrc* pVictimUnit = pOperation->sArg.pVictim;
    if (!pVictimUnit || pVictimUnit->eAnimMode.ePlayerMode == Death) {
      int32_t nTradeTick;
      nTradeTick = PLAYER::Player::GetPlayerTradeTickOrBusy(pOperation->pAttacker);
      if (nTradeTick != 1) {
        _bHasGemInInventory = OBJMODE_CheckInventoryHasItemType(ITEMTYPE_Gem, pOperation->pAttacker);
        if (!_bHasGemInInventory) {
          UNIT::SUnit::SetupUpdateEvent_AttachEventSound(pOperation->pAttacker, 0x13, pOperation->pAttacker);
          return 1;
        }

        pVictimUnit = pOperation->sArg.pVictim;
        if (!pVictimUnit) {
          nCubeUnitGUID = -1;
        } else {
          nCubeUnitGUID = pVictimUnit->nUnitGUID;
        }

        UNIT::SUnit::SetInteractInfo(pOperation->pAttacker, UNIT_OBJECT, nCubeUnitGUID);
        D2Common::Units::SetupUpdateFlag(pOperation->sArg.pVictim, 3);
        pVictimUnit = pOperation->sArg.pVictim;
        sPacket.nPacketId = 'X';
        if (!pVictimUnit) {
          sPacket.nUnitGUID = -1;
        } else {
          sPacket.nUnitGUID = pVictimUnit->nUnitGUID;
        }

        sPacket.nUIType = '\0';
        GAME::SCmd::NET_D2GS_SERVER_Send_0x58_ITEMACCEPT(pClient, &sPacket);
      }
    } else if (pVictimUnit->eAnimMode.ePlayerMode == eD2PlayerAnimMode_ns::Run && pNpc == pVictimUnit) {
      UNIT::SUnit::ClearInteractInfo(pOperation->pAttacker);
      D2Common::Units::SetupUpdateFlag(pOperation->sArg.pVictim, 1);
      return 1;
    }

    return 1;
}

// Returns 1 if pUnit is a valid targetable monster for pUnit2 (e.g. for shrine/object counter-attack targeting). Checks: pUnit != pUnit2, is UNIT_MONSTER, not an ally of pUnit2, neutral alignment, not dead, in Neutral or Walk anim mode, has the required monster stat flag (index 2), has a non-zero Height in MonStats2, and is neither a boss nor flagged by MonStatFlag bit 7 nor of type 0x1F. Returns 0 otherwise.
uint32_t __fastcall OBJECT_CanTargetMonster(D2UnitStrc * pUnit, D2UnitStrc * pUnit2) {
    BOOL _bIsAlly;
    bool bIsAlly;
    bool bIsDead;
    if (pUnit == pUnit2) {
      return 0;
    }
    if (!pUnit) {
      return 0;
    }
    if (pUnit->eUnitType != UNIT_MONSTER) {
      return 0;
    }

    _bIsAlly = D2Common::PATH::Path::IsAllyOf(pUnit2, pUnit);
    if (_bIsAlly == 1) {
      return 0;
    }

    int32_t nAlignment = D2Common::Stats::StatsEx::STATSEX_GetAlignment(pUnit);
    if (nAlignment) {
      return 0;
    }

    _bIsAlly = D2Common::Monsters::MONSTERS::CheckIfMonsterIsDead(pUnit);
    if (_bIsAlly) {
      return 0;
    }
    if (!(pUnit->eAnimMode.ePlayerMode == eD2PlayerAnimMode_ns::Neutral || pUnit->eAnimMode.ePlayerMode == Walk)) {
      return 0;
    }

    nAlignment = pUnit->nClassId;
    uint32_t uStatFlag = D2Client::Source::ClientEngine::GetSomeMonsterStatFlag(nAlignment, 2);
    if (!uStatFlag) {
      return 0;
    }

    D2MonStats2Txt* pMonStats2 = D2Client::DataTbls::MonsterTbls::TXT_MonStats_GetMonStats2(nAlignment);
    if (!(pMonStats2 && pMonStats2->Height != '\0')) {
      return 0;
    }

    D2MonStatsTxt* pMonStats = ITEMS::ItemMode::GetMonsterData(pUnit);
    if (!pMonStats) {
      return 0;
    }

    uStatFlag = D2Common::Monsters::MONSTERS::UnitIsMarkedBoss(pMonStats, pUnit);
    if (uStatFlag) {
      return 0;
    }

    uStatFlag = D2Common::Monsters::MONSTERS::MONSTERS_CheckMonStatFlag0xc_Bit7(pUnit);
    if (!uStatFlag) {
      uStatFlag = Monsters::CheckMonsterType(pUnit, 0x1f);
      return (uint32_t)!uStatFlag;
    }

    return 0;
}

