// Two GuardStack tails: GuardStack(1) after successful spawn/removal, GuardStack(nReturnValue) where nReturnValue is explicitly set to 0 (no spawn spot) or 1 (spawned) elsewhere.
static BOOL __stdcall Shrines_GemShrine_SpawnGem(int32_t nItemClassId, D2UnitStrc * pUnit, ::SGAMEDATA * pGame, D2UnitStrc * pUnit2) {
    BOOL BVar1;
    POINT ptUnitCoords;
    POINT ptSpawnPos;
    D2ItemGenContextStrc sItemGenCtx;
    D2UnitStrc* pNewGemItem;
    D2UnitStrc* pOldGemItem;
    D2Common::Units::GetCoords(pUnit2, &ptUnitCoords);
    uint8_t bSearchNeighbors = 1;
    uint32_t uSearchFlag = 1;
    POINT* pNewPosition = &ptSpawnPos;
    D2RoomStrc* pRoom = D2Common::Units::UNITS_GetRoom(pUnit2);
    D2UnitStrc* pSpawnedItem = (D2UnitStrc*)ITEMS::Items::Drop::FindBestSpotToSpawnItem(pRoom, &ptUnitCoords, pNewPosition, uSearchFlag, bSearchNeighbors);
    if (pSpawnedItem) {
      eInventoryPage ePreviousPage;
      memset(&sItemGenCtx, 0, 0x84);
      sItemGenCtx.pUnit = 0;
      sItemGenCtx.pSeed = 0;
      sItemGenCtx.wItemFormat = pGame->wItemFormat;
      sItemGenCtx.nItemClassid = nItemClassId;
      sItemGenCtx.nPosX = ptSpawnPos.x;
      sItemGenCtx.pDrlgRoom = (D2RoomStrc*)pSpawnedItem;
      sItemGenCtx.dwMode = 3;
      sItemGenCtx.nPosY = ptSpawnPos.y;
      sItemGenCtx.usually_one = 1;
      sItemGenCtx.eQuality = QUALITY_NORMAL;
      sItemGenCtx.pGame = pGame;
      sItemGenCtx.nItemLevel = ITEMS::Items::Drop::GetLevel(pUnit2, LEVEL_None);
      pSpawnedItem = ITEMS::Items::Drop::ITEM_CreateItemInstance(pGame, &sItemGenCtx, 0);
      D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pSpawnedItem, UNITSTAT_quantity, 1, 0);
      D2Common::Unit::ROOM_LinkUnitToUpdateList(pSpawnedItem);
      if (pSpawnedItem) {
        pSpawnedItem->eUnitFlags |= UNITFLAG_DOUPDATE;
      }

      BVar1 = 1;
      if (pUnit) {
        pSpawnedItem = 0;
        D2Common::ITEMS::Items::ITEM_SetServerSideFlag((uint32_t*)&pSpawnedItem, 0x20, 1);
        ePreviousPage = D2Common::ITEMS::Items::ITEM_GetContainingInventoryPage(pUnit);
        D2Common::ITEMS::Items::ITEM_SetItemData_ePreviousPage(pUnit, ePreviousPage);
        pOldGemItem = pUnit;
        pNewGemItem = pSpawnedItem;
        GAME::SCmd::Send0x9DRemoveItemFromContainer(UNIT::SUnit::SUNIT_GetClient(pUnit2, ".\\OBJECTS\\ObjMode.cpp", 0x80f), pUnit2, pOldGemItem, (eD2ItemFlag)pNewGemItem);
        ITEMS::ItemMode::ITEMMODE_DeleteItemFromInventory(pGame, pUnit2, pUnit, 0);
        return 1;
      }
    } else {
      BVar1 = 0;
      pSpawnedItem = 0;
    }

    return BVar1;
}

// Gem Shrine activation handler. Iterates the activating player's gem inventory (type 0x14) and upgrades the first upgradeable gem by spawning its BetterGem entry via Shrines_GemShrine_SpawnGem. If no upgrade is possible (no gems or all already max-grade), picks a random chipped gem type (gcw/gcr/gcg/gcb/gcy/gcv) by seeding on the player unit and spawns it. Halts with an internal error if a gem item code fails to resolve.
void __fastcall Shrines_GemShrineFunction(D2ObjectOperateFnArg * pArguments, D2ShrinesTxt * pTxtShrines) {
    int32_t nItemClassId;
    BOOL bGemSpawnSucceeded;
    uint32_t acItemCode;
    D2InventoryStrc* pInventory = pArguments->pAttacker->pInventory;
    D2UnitStrc* pGemItem = D2Common::INVENTORY::Inventory::INVENTORY_FindItemByType(pInventory, 0x14, nullptr);
    bool bUpgradePerformed = false;
    if (pGemItem) {
      D2ItemsTxt* pItemTxt;
      do {
        if (bUpgradePerformed) {
          return;
        }
        if (!pGemItem) {
          acItemCode = -1;
        } else {
          acItemCode = pGemItem->nClassId;
        }

        pItemTxt = D2Common::DATATBLS::ItemTbls::TXT_Items_GetLine(acItemCode);
        if (pItemTxt->dwBetterGem != 0x206e6f6e) {
          nItemClassId = D2Common::DATATBLS::ItemTbls::TXT_Items_ConvertItemCodeToItemClassId(pItemTxt->dwBetterGem);
          if (nItemClassId == -1) {
            Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x823);
            exit(-1);
          }

          bGemSpawnSucceeded = Shrines_GemShrine_SpawnGem(nItemClassId, pGemItem, pArguments->sArg.pGame, pArguments->pAttacker);
          if (bGemSpawnSucceeded) {
            bUpgradePerformed = true;
            pGemItem = 0;
          }
        }

        pGemItem = D2Common::INVENTORY::Inventory::INVENTORY_FindItemByType(pInventory, 0x14, pGemItem);
      } while (pGemItem);

      if (bUpgradePerformed) {
        return;
      }
    }

    pGemItem = pArguments->pAttacker;
    D2SeedStrc sNewSeed = D2_SEED_NEXT(pGemItem->sSeed);
    pGemItem->sSeed.nSeedHigh = sNewSeed.nSeedHigh;
    pGemItem->sSeed.nSeedLow = sNewSeed.nSeedLow;
    switch (sNewSeed.nSeedLow % 6) {
      case 0:
        acItemCode = 0x20776367;
      break;
      case 1:
        acItemCode = 0x20726367;
      break;
      case 2:
        acItemCode = 0x20676367;
      break;
      case 3:
        acItemCode = 0x20626367;
      break;
      case 4:
        acItemCode = 0x20796367;
      break;
      default:
        acItemCode = 0x20766367;
    }

    nItemClassId = D2Common::DATATBLS::ItemTbls::TXT_Items_ConvertItemCodeToItemClassId(acItemCode);
    if (nItemClassId == -1) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x84c);
      exit(-1);
    }

    Shrines_GemShrine_SpawnGem(nItemClassId, nullptr, pArguments->sArg.pGame, pArguments->pAttacker);
    return;
}

// Server-side activation effect for a Storm/Tempest shrine (operate handler, D2ObjectOperateFnArg + ShrinesTxt). Two-phase: (1) finds all alive units within ShrinesTxt.dwArg1 tiles of the operating unit via InitializeUnitFindData/FindAllMatchingUnitsInNeighboredRooms and drains a percentage (dwArg0-based, ~ /100) of each monster/player target's hitpoints via STATLIST_AddUnitStat; (2) spawns a 5x5 ring/grid of MISSILE_Fireball missiles around the unit (offsets -5..+25 step 5, alternating sides), owned by pAttacker, with missile level capped 1..8 from the owner's level/5. No return.
void __fastcall Shrines_StormShrineFunction(D2ObjectOperateFnArg * pArguments, D2ShrinesTxt * pTxtShrines) {
    int nHpReduction;
    bool bAltSide;
    int nUnitIdx;
    D2UnitFindArgStrc sUnitFindArg;
    D2SkillArgStrc sSkillArg;
    D2UnitFindDataStrc unitFindData;
    uint32_t nRowParity;
    int nNegColOffset;
    D2ShrinesTxt* pTxtShrinesLocal = pTxtShrines;
    D2RoomStrc* pRoom = D2Common::Units::UNITS_GetRoom(pArguments->sArg.pVictim);
    D2UnitStrc* pTargetUnit = pArguments->sArg.pVictim;
    eD2UnitType eUnitType = pTargetUnit->eUnitType;
    if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
      nUnitIdx = pTargetUnit->pPath.pStaticPath->nPosX;
    } else if (pTargetUnit->pPath.pDynamicPath) {
      nUnitIdx = D2Common::PATH::DynamicPath::GetXPos(pTargetUnit->pPath.pDynamicPath);
    } else {
      nUnitIdx = 0;
    }

    pTargetUnit = pArguments->sArg.pVictim;
    eUnitType = pTargetUnit->eUnitType;
    if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
      sUnitFindArg.nY = pTargetUnit->pPath.pStaticPath->nPosY;
    } else if (pTargetUnit->pPath.pDynamicPath) {
      sUnitFindArg.nY = D2Common::PATH::DynamicPath::GetYPos(pTargetUnit->pPath.pDynamicPath);
    } else {
      sUnitFindArg.nY = 0;
    }

    memset(&sUnitFindArg, 0, 0x38);
    sUnitFindArg.nDistance = pTxtShrinesLocal->dwArg1;
    sUnitFindArg.nFlags = 0x583;
    sUnitFindArg.nX = nUnitIdx;
    D2Common::Units::UnitFinds::InitializeUnitFindData(pArguments->sArg.pGame->pMemoryPool, &unitFindData, pRoom, nUnitIdx, sUnitFindArg.nY, sUnitFindArg.nDistance, (UNITFINDTEST)UNIT_IsAlive, &sUnitFindArg);
    D2Common::Units::UnitFinds::UNITFINDS_FindCullRange(&unitFindData);
    nUnitIdx = 0;
    if (unitFindData.nCountedUnits > 0) {
      BOOL bIsDead;
      do {
        pTargetUnit = unitFindData.pUnitsArray->aFoundUnitsList[nUnitIdx];
        if (pTargetUnit && (pTargetUnit->eUnitType == UNIT_MONSTER || pTargetUnit->eUnitType == UNIT_PLAYER)) {
          bIsDead = UNIT::SUnit::CheckForModeZeroDeath(pTargetUnit);
          if (!bIsDead) {
            nHpReduction = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pTargetUnit, UNITSTAT_hitpoints, 0);
            nHpReduction = (int)((uint64_t)((int64_t)(int)(pTxtShrinesLocal->dwArg0 * (nHpReduction >> 8)) * -0x51eb851f) >> 0x20);
            D2Common::Stats::StatsEx::STATLIST_AddUnitStat(pTargetUnit, UNITSTAT_hitpoints, ((nHpReduction >> 5) - (nHpReduction >> 0x1f)) * 0x100, 0);
          }
        }

        nUnitIdx++;
      } while (nUnitIdx < unitFindData.nCountedUnits);
    }

    D2Common::Units::UnitFinds::FreeUnitFindData(&unitFindData);
    uint32_t nRingRow = 1;
    pTxtShrinesLocal = (D2ShrinesTxt*)-5;
    pRoom = (D2RoomStrc*)0x5;
    do {
      bAltSide = true;
      nRowParity = nRingRow & 1;
      nNegColOffset = -5;
      nUnitIdx = 5;
      do {
        memset(&sSkillArg, 0, 0x5c);
        pTargetUnit = pArguments->sArg.pVictim;
        sSkillArg.nFlags = 3;
        eUnitType = pTargetUnit->eUnitType;
        if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
          sSkillArg.nX = pTargetUnit->pPath.pStaticPath->nPosX;
        } else if (pTargetUnit->pPath.pDynamicPath) {
          sSkillArg.nX = D2Common::PATH::DynamicPath::GetXPos(pTargetUnit->pPath.pDynamicPath);
        } else {
          sSkillArg.nX = 0;
        }

        pTargetUnit = pArguments->sArg.pVictim;
        eUnitType = pTargetUnit->eUnitType;
        if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
          sSkillArg.nY = pTargetUnit->pPath.pStaticPath->nPosY;
        } else if (pTargetUnit->pPath.pDynamicPath) {
          sSkillArg.nY = D2Common::PATH::DynamicPath::GetYPos(pTargetUnit->pPath.pDynamicPath);
        } else {
          sSkillArg.nY = 0;
        }
        if (nRowParity) {
          sSkillArg.nUnitX = (int)pRoom;
        } else {
          sSkillArg.nUnitX = (int)pTxtShrinesLocal;
        }

        sSkillArg.nUnitY = nUnitIdx;
        if (!bAltSide) {
          sSkillArg.nUnitY = nNegColOffset;
        }

        sSkillArg.pOwner = pArguments->pAttacker;
        sSkillArg.nMissileTxtNo = MISSILE_Fireball;
        sSkillArg.nSkillLevel = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(sSkillArg.pOwner, UNITSTAT_level, 0);
        sSkillArg.nSkillLevel /= 5;
        if (sSkillArg.nSkillLevel < 1) {
          sSkillArg.nSkillLevel = 1;
        } else if (sSkillArg.nSkillLevel > 8) {
          sSkillArg.nSkillLevel = 8;
        }

        MISSILES::Missiles::CreatingMissile(pArguments->sArg.pGame, &sSkillArg);
        nNegColOffset += -5;
        nUnitIdx += 5;
        bAltSide = (bool)(bAltSide ^ 1);
      } while (nUnitIdx < 0x19);

      nRingRow++;
      pTxtShrinesLocal = (D2ShrinesTxt*)((int)pTxtShrinesLocal - 5);
      pRoom = (D2RoomStrc*)((int)pRoom + 5);
    } while ((int)pRoom < 0x19);
}

void __fastcall Shrines_WarpingShrineFunction(D2ObjectOperateFnArg * pArguments, D2ShrinesTxt * pTxtShrines) {
    int nAttackerPosY;
    int32_t nAttackerPosX;
    D2UnitStrc* pUnit = pArguments->pAttacker;
    eD2UnitType eUnitType = pUnit->eUnitType;
    if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
      nAttackerPosY = pUnit->pPath.pStaticPath->nPosY;
    } else if (pUnit->pPath.pDynamicPath) {
      nAttackerPosY = D2Common::PATH::DynamicPath::GetYPos(pUnit->pPath.pDynamicPath);
    } else {
      nAttackerPosY = 0;
    }

    pUnit = pArguments->pAttacker;
    eUnitType = pUnit->eUnitType;
    if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
      nAttackerPosX = pUnit->pPath.pStaticPath->nPosX;
    } else if (pUnit->pPath.pDynamicPath) {
      nAttackerPosX = D2Common::PATH::DynamicPath::GetXPos(pUnit->pPath.pDynamicPath);
    } else {
      nAttackerPosX = 0;
    }

    pUnit = D2Common::Units::UnitFinds::GetNearestTestedUnit(pArguments->pAttacker, nAttackerPosX, nAttackerPosY, 0, (fpUnitTest)OBJECT_CanTargetMonster);
    if (!pUnit) {
      return;
    }

    Monsters::MONSTER_PromoteToUnique(pArguments->sArg.pGame, pUnit);
}

// Operate handler for an exploding/gizzard shrine (D2ObjectOperateFnArg + D2ShrinesTxt). Uses the shrine victim's RNG seed to roll a count between dwArg0..dwArg1, then spawns that many "opm " (mana potion) items near the attacker via FindBestSpotToSpawnItem + ITEM_CreateItemInstance (quantity 1, mode 3), linking each to the room update list. Then fires a fixed ring of 6 missiles (CreatingMissile) at offsets (+/-6,-6) around the shrine's position, with skill level = clamp(attacker level/5, 1..8). Server-side object operate effect; no return.
void __fastcall Shrines_ExplodingShrineFunction(D2ObjectOperateFnArg * pArguments, D2ShrinesTxt * pTxtShrines) {
    D2RoomStrc* pSpawnRoom;
    int nLevel;
    uint32_t nCollisionMask;
    POINT ptAttackerCoords;
    int aMissileOffsets[13];
    POINT ptSpawnPos;
    D2ItemGenContextStrc sItemGenCtx;
    uint8_t bSearchNeighbors;
    eD2UnitType eUnitType;
    int64_t lSeedProduct;
    POINT* pNewPosition;
    D2SeedStrc sNewSeed;
    uint32_t uSeedHigh = pTxtShrines->dwArg1 - pTxtShrines->dwArg0;
    D2UnitStrc* pCreatedItem = pArguments->sArg.pVictim;
    D2SeedStrc* pSeed = &pCreatedItem->sSeed;
    if ((int)uSeedHigh <= 0) {
      uSeedHigh = 0;
    } else if (uSeedHigh & uSeedHigh - 1) {
      lSeedProduct = (uint64_t)pSeed->nSeedLow * 0x6ac690c5;
      ptSpawnPos.y = (LONG)((uint64_t)lSeedProduct >> 0x20);
      sNewSeed = (D2SeedStrc)(lSeedProduct + (uint64_t)pCreatedItem->sSeed.nSeedHigh);
      pSeed->nSeedHigh = sNewSeed.nSeedHigh;
      pSeed->nSeedLow = sNewSeed.nSeedLow;
      uSeedHigh = sNewSeed.nSeedLow % uSeedHigh;
    } else {
      lSeedProduct = (uint64_t)pSeed->nSeedLow * 0x6ac690c5;
      ptSpawnPos.y = (LONG)((uint64_t)lSeedProduct >> 0x20);
      sNewSeed = (D2SeedStrc)(lSeedProduct + (uint64_t)pCreatedItem->sSeed.nSeedHigh);
      pSeed->nSeedHigh = sNewSeed.nSeedHigh;
      pSeed->nSeedLow = sNewSeed.nSeedLow;
      uSeedHigh = uSeedHigh - 1 & sNewSeed.nSeedLow;
    }

    aMissileOffsets[0xc] = pTxtShrines->dwArg0 + uSeedHigh;
    int nPotionSpawnIdx = 0;
    if (aMissileOffsets[0xc] > 0) {
      int32_t nItemClassId;
      do {
        nItemClassId = D2Common::DATATBLS::ItemTbls::TXT_Items_ConvertItemCodeToItemClassId(0x206d706f);
        if (nItemClassId == -1) {
          Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x8b2);
          exit(-1);
        }

        D2Common::Units::GetCoords(pArguments->pAttacker, &ptAttackerCoords);
        bSearchNeighbors = 1;
        nCollisionMask = 1;
        pNewPosition = &ptSpawnPos;
        pSpawnRoom = D2Common::Units::UNITS_GetRoom(pArguments->pAttacker);
        pSpawnRoom = ITEMS::Items::Drop::FindBestSpotToSpawnItem(pSpawnRoom, &ptAttackerCoords, pNewPosition, nCollisionMask, bSearchNeighbors);
        if (pSpawnRoom) {
          memset(&sItemGenCtx, 0, 0x84);
          sItemGenCtx.pGame = pArguments->sArg.pGame;
          sItemGenCtx.pUnit = 0;
          sItemGenCtx.pSeed = 0;
          sItemGenCtx.nPosY = ptSpawnPos.y;
          sItemGenCtx.eQuality = QUALITY_INVALID;
          sItemGenCtx.dwMode = 3;
          sItemGenCtx.nPosX = ptSpawnPos.x;
          sItemGenCtx.wItemFormat = sItemGenCtx.pGame->wItemFormat;
          sItemGenCtx.usually_one = 1;
          sItemGenCtx.nItemClassid = nItemClassId;
          sItemGenCtx.pDrlgRoom = pSpawnRoom;
          sItemGenCtx.nItemLevel = ITEMS::Items::Drop::GetLevel(pArguments->pAttacker, LEVEL_None);
          sItemGenCtx.nPresetQuantity = 1;
          pCreatedItem = ITEMS::Items::Drop::ITEM_CreateItemInstance(pArguments->sArg.pGame, &sItemGenCtx, 0);
          D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pCreatedItem, UNITSTAT_quantity, 1, 0);
          D2Common::Unit::ROOM_LinkUnitToUpdateList(pCreatedItem);
          if (pCreatedItem) {
            pCreatedItem->eUnitFlags |= UNITFLAG_DOUPDATE;
          }
        }

        nPotionSpawnIdx++;
      } while (nPotionSpawnIdx < aMissileOffsets[0xc]);
    }

    int iMissileIdx = 0;
    aMissileOffsets[6] = -6;
    aMissileOffsets[7] = -6;
    aMissileOffsets[8] = 0;
    aMissileOffsets[9] = 0;
    aMissileOffsets[10] = 6;
    aMissileOffsets[0xb] = 6;
    aMissileOffsets[0] = 6;
    aMissileOffsets[1] = -6;
    aMissileOffsets[2] = 6;
    aMissileOffsets[3] = -6;
    aMissileOffsets[4] = 6;
    aMissileOffsets[5] = -6;
    do {
      memset(&sItemGenCtx.usually_one, 0, 0x5c);
      pCreatedItem = pArguments->sArg.pVictim;
      sItemGenCtx.usually_one = 0x520;
      sItemGenCtx.wItemFormat = 0;
      eUnitType = pCreatedItem->eUnitType;
      if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
        sItemGenCtx.maxDurability = pCreatedItem->pPath.pStaticPath->nPosX;
      } else if (pCreatedItem->pPath.pDynamicPath) {
        sItemGenCtx.maxDurability = D2Common::PATH::DynamicPath::GetXPos(pCreatedItem->pPath.pDynamicPath);
      } else {
        sItemGenCtx.maxDurability = 0;
      }

      pCreatedItem = pArguments->sArg.pVictim;
      eUnitType = pCreatedItem->eUnitType;
      if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
        sItemGenCtx.dwFileIndex = pCreatedItem->pPath.pStaticPath->nPosY;
      } else if (pCreatedItem->pPath.pDynamicPath) {
        sItemGenCtx.dwFileIndex = D2Common::PATH::DynamicPath::GetYPos(pCreatedItem->pPath.pDynamicPath);
      } else {
        sItemGenCtx.dwFileIndex = 0;
      }

      sItemGenCtx.neD2ItemFlag = aMissileOffsets[iMissileIdx + 6] + sItemGenCtx.maxDurability;
      sItemGenCtx.nInitSeed = aMissileOffsets[iMissileIdx] + sItemGenCtx.dwFileIndex;
      sItemGenCtx.bFromCustomData = (int)pArguments->pAttacker;
      sItemGenCtx.eQuality = (eD2ItemQuality)pArguments->sArg.pVictim;
      sItemGenCtx.nModSeed = 1;
      sItemGenCtx.durability = 0x2d;
      nLevel = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat((D2UnitStrc*)sItemGenCtx.bFromCustomData, UNITSTAT_level, 0);
      *(uint32_t*)(char*)&sItemGenCtx.szCustomName = nLevel / 5;
      if ((int)*(uint32_t*)(char*)&sItemGenCtx.szCustomName < 1) {
        *(uint32_t*)(char*)&sItemGenCtx.szCustomName = 1;
      } else if ((int)*(uint32_t*)(char*)&sItemGenCtx.szCustomName > 8) {
        *(uint32_t*)(char*)&sItemGenCtx.szCustomName = 8;
      }

      MISSILES::Missiles::CreatingMissile(pArguments->sArg.pGame, (D2SkillArgStrc*)&sItemGenCtx.usually_one);
      iMissileIdx++;
    } while (iMissileIdx < 6);
}

